<script setup lang="ts">
import { onMounted, ref } from "vue";import { useRoute } from "vue-router";import { http } from "@/utils/http";import { message } from "@/utils/message";
const route=useRoute(), orders=ref<any[]>([]), warehouses=ref<any[]>([]), products=ref<any[]>([]), selected=ref<any>(null), rows=ref<any[]>([]), warehouseId=ref<number>(), remark=ref(""), loading=ref(false), saving=ref(false);
async function load(){loading.value=true;try{const [r,w,p]:any[]=await Promise.all([http.request("get","/purchase-order",{params:{page:1,pageSize:100}}),http.request("get","/warehouse/options"),http.request("get","/product/options")]);orders.value=(r.data?.list??[]).filter((x:any)=>x.orderStatus===1||x.orderStatus===2);warehouses.value=w.data??[];products.value=p.data??[];const id=Number(route.query.orderId);if(id) await selectOrder(id)}catch(e:any){message(e?.message||"加载失败",{type:"error"})}finally{loading.value=false}}
async function selectOrder(id:number){try{const r:any=await http.request("get",`/purchase-order/${id}`);if(r.code!==0){message(r.message,{type:"error"});return}selected.value=r.data;rows.value=(r.data.lines??[]).filter((x:any)=>Number(x.qty)>Number(x.receivedQty)).map((x:any)=>({...x,receiveQty:Number(x.qty)-Number(x.receivedQty),batchNo:"",location:""}))}catch(e:any){message(e?.message||"订单详情加载失败",{type:"error"})}}
async function receive(){if(!selected.value||!warehouseId.value||!rows.value.length||!rows.value.some(x=>Number(x.receiveQty)>0)||rows.value.some(x=>Number(x.receiveQty)<0||Number(x.receiveQty)>Number(x.qty)-Number(x.receivedQty))){message("请选择仓库并填写不超过未收数量的正数",{type:"warning"});return} saving.value=true;try{const r:any=await http.request("post",`/purchase-order/${selected.value.id}/receive`,{data:{warehouseId:warehouseId.value,remark:remark.value||null,items:rows.value.filter(x=>Number(x.receiveQty)>0).map(x=>({lineId:x.id,qty:Number(x.receiveQty),batchNo:x.batchNo||null,location:x.location||null}))}});if(r.code===0){message("收货完成，库存已过账",{type:"success"});await selectOrder(selected.value.id)}else message(r.message,{type:"error"})}catch(e:any){message(e?.response?.data?.message||e?.message||"收货失败",{type:"error"})}finally{saving.value=false}}
onMounted(load);
</script>
<template><el-card shadow="never"><div class="toolbar"><strong>采购收货 / 库存入库</strong><el-button @click="$router.push('/purchase/order')">采购订单</el-button></div><el-form inline><el-form-item label="采购订单"><el-select :model-value="selected?.id" filterable placeholder="选择已确认订单" style="width:360px" @change="selectOrder"><el-option v-for="o in orders" :key="o.id" :label="`${o.code} - ${o.name||''}`" :value="o.id"/></el-select></el-form-item><el-form-item label="入库仓库"><el-select v-model="warehouseId" filterable placeholder="选择仓库" style="width:220px"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item></el-form><el-alert v-if="selected" :title="`订单 ${selected.code} | 供应商 ${selected.name||'-'} | 状态 ${selected.orderStatus===2?'部分收货':'已确认'}`" type="info" :closable="false" style="margin-bottom:14px"/><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="seq" label="行" width="60"/><el-table-column label="产品" min-width="180"><template #default="{row}">{{products.find((x:any)=>x.id===row.productId)?.name||`产品#${row.productId}`}}</template></el-table-column><el-table-column prop="qty" label="订单数量" width="120"/><el-table-column prop="receivedQty" label="已收数量" width="120"/><el-table-column label="本次收货" width="190"><template #default="{row}"><el-input-number v-model="row.receiveQty" :min="0" :max="Number(row.qty)-Number(row.receivedQty)" :precision="3" controls-position="right"/></template></el-table-column><el-table-column prop="price" label="单价" width="110"/><el-table-column label="批次" width="160"><template #default="{row}"><el-input v-model="row.batchNo" placeholder="可选"/></template></el-table-column><el-table-column label="库位" width="140"><template #default="{row}"><el-input v-model="row.location" placeholder="可选"/></template></el-table-column><el-table-column label="预计到货"><template #default="{row}">{{row.expectedDate?String(row.expectedDate).slice(0,10):"-"}}</template></el-table-column></el-table><el-form label-width="90px" style="margin-top:14px"><el-form-item label="收货备注"><el-input v-model="remark" type="textarea" :rows="2"/></el-form-item></el-form><div class="actions"><el-button type="primary" :disabled="!selected" :loading="saving" @click="receive">确认收货并过账</el-button></div><el-empty v-if="selected&&rows.length===0" description="该采购订单已全部收货"/></el-card></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.actions{display:flex;justify-content:flex-end;margin-top:12px}</style>
